// @ts-check
import { defineConfig } from 'astro/config';
import tailwind from '@astrojs/tailwind';
import sitemap from '@astrojs/sitemap';
import { readFileSync } from 'node:fs';

const BUILD_DATE = new Date().toISOString();
// Real per-page change dates, generated by scripts/lastmod.mjs (npm run lastmod).
const LASTMOD = JSON.parse(readFileSync(new URL('./src/data/lastmod.json', import.meta.url), 'utf8'));

export default defineConfig({
  site: 'https://alturascope.com',
  trailingSlash: 'always',
  // /uk/heritage-building-documentation/ duplicated /uk/heritage-building-survey/
  // and had no inbound links at all - two UK pages competing for the same query.
  // Astro emits a meta-refresh page with a canonical for static builds; the
  // nginx config also carries a real 301 (see docs/deployment/redirects.md).
  redirects: {
    // Pruned Aug 2026: 28 service pages spanning superyachts, private aircraft,
    // solar farms and art collections diluted what the site is about and
    // competed with the sectors we actually sell. Folded into the page that
    // already exists for exactly this work.
    '/services/superyacht-documentation/': '/services/specialist-projects/',
    '/services/private-aircraft-documentation/': '/services/specialist-projects/',
    '/services/private-collection-documentation/': '/services/specialist-projects/',
    '/services/private-estate-documentation/': '/services/specialist-projects/',
    '/services/film-tv-location-documentation/': '/services/specialist-projects/',
    '/services/solar-farm-documentation/': '/services/specialist-projects/',
    '/services/aviation-facility-survey/': '/services/specialist-projects/',
    '/services/resort-hotel-capex-survey/': '/services/specialist-projects/',
    // The sector is dropped, but the data centre *article* stays - it is the
    // single highest-impression page on the site (233 impressions, position 20.9).
    '/services/data-centre-documentation/': '/services/industrial-facility-documentation/',
    '/uk/heritage-building-documentation/': '/uk/',
    // Pruned 2026-10-26: Google crawled these and declined to index them -
    // generic, overlapping articles from the first content batch. Each folds
    // into the closest page that is indexed and earning impressions.
    '/insights/aba-clinic-portfolio-renovation-documentation/': '/insights/aba-multi-location-growth-documentation-strategy/',
    '/insights/convenience-fuel-retail-site-survey-rollout/': '/services/retail-rollout-documentation/',
    '/insights/data-center-documentation-expansion-retrofit/': '/insights/documenting-controlled-environments-precision-facilities/',
    '/insights/franchise-expansion-shell-survey-new-locations/': '/insights/second-generation-space-what-to-verify-before-you-sign/',
    '/insights/healthcare-multi-site-facility-survey-documentation/': '/services/healthcare-facility-survey/',
    '/insights/managing-multi-site-survey-programmes-at-scale/': '/insights/standardising-site-surveys-multi-site-operators/',
    '/insights/multi-site-brand-standard-compliance-documentation/': '/insights/standardising-site-surveys-multi-site-operators/',
    '/insights/point-cloud-as-built-survey-architects-engineers/': '/services/construction-documentation/',
    '/insights/qsr-franchise-kitchen-equipment-documentation/': '/insights/grease-power-water-food-unit-fit-out/',
    '/insights/self-storage-portfolio-site-survey-documentation/': '/insights/due-diligence-documentation-portfolio-acquisitions/',
    '/services/self-storage-portfolio-documentation/': '/services/specialist-projects/',
    '/insights/site-documentation-heritage-complex-specialist-buildings/': '/services/specialist-projects/',
    '/insights/uk-retail-high-street-refurbishment-survey/': '/uk/multi-site-rollout-survey/',
    '/insights/vehicle-dealership-renovation-site-survey/': '/services/retail-rollout-documentation/',
    '/insights/why-poor-site-documentation-costs-construction-projects/': '/insights/what-should-a-professional-site-survey-include/',
  },
  build: {
    // Inline the stylesheet into every page instead of linking a content-hashed
    // file. A deploy changes that hash, so any browser holding cached HTML from
    // before the deploy requests a stylesheet that no longer exists and renders
    // the page completely unstyled. Inlining removes the request, and therefore
    // the failure: stale HTML still paints correctly using its own styles.
    inlineStylesheets: 'always',
  },
  integrations: [
    tailwind(),
    sitemap({
      // sample-project is a noindex demo; listing it in the sitemap sends Google
      // a contradiction it reports as an error.
      filter: (page) => !page.includes('/thank-you/') && !page.includes('/work/sample-project/'),
      // /work/walkthrough/ (static exhibit in public/) is deliberately not listed:
      // it is a full-screen viewer with no text for Google to index.
      // Give crawlers a change signal. Without lastmod, a recrawl of an updated
      // page can lag by weeks - which is why new services were slow to surface.
      serialize(item) {
        const url = item.url;
        item.lastmod = LASTMOD[new URL(url).pathname] ?? BUILD_DATE;
        if (url === 'https://alturascope.com/') {
          item.changefreq = 'weekly';
          item.priority = 1.0;
        } else if (/\/(estimating|services|work|uk)\/?$/.test(url)) {
          item.changefreq = 'weekly';
          item.priority = 0.9;
        } else if (url.includes('/estimating/') || url.includes('/work/')) {
          item.changefreq = 'monthly';
          item.priority = 0.8;
        } else if (url.includes('/insights/')) {
          item.changefreq = 'monthly';
          item.priority = 0.6;
        } else {
          item.changefreq = 'monthly';
          item.priority = 0.7;
        }
        return item;
      },
    }),
  ],
});
